"""Curated English, level-relative screening items. Never generated by an LLM.

v1 is immutable: publish a new version when wording/options/keys change. Attempts
snapshot all private items so deployed revisions cannot change an in-flight test.
"""
import re
import random
from functools import lru_cache
from ..schemas import EducationLevel, ProfileDetails, Question, Option

VERSION = 'student-calibration-v1'


def q(key, dimension, prompt, options, correct, difficulty=0.5):
    choices = [Option(id=chr(97 + index), text=text) for index, text in enumerate(options)]
    return Question(id=key, dimension=dimension, prompt=prompt, options=choices,
                    correct_option_id=choices[correct].id, difficulty=difficulty,
                    kind='true_false' if options == ['True', 'False'] else 'mcq')


