def field_domain(field):
    patterns = {
        'computing': r'\b(computer|computing|software|programming|informatics|data science)\b',
        'health': r'\b(medicine|medical|nursing|health|pharmacy|dentistry)\b',
        'business': r'\b(business|commerce|finance|accounting|economics|management)\b',
        'humanities': r'\b(history|literature|language|philosophy|humanities|law|arts)\b',
        'stem': r'\b(science|physics|chemistry|biology|engineering|mathematics|maths|math)\b',
    }
    return next((domain for domain, pattern in patterns.items() if re.search(pattern, field, re.I)), 'general')


def blueprint(details: ProfileDetails, seed: str | None = None):
    from .domains import domain_questions
    level = details.education_level.value
    domain = field_domain(details.field_of_study) if level in {'high_school', 'college', 'undergraduate', 'graduate'} else 'general'
    items = [item.model_copy(deep=True) for item in banks()[level]]
    if domain != 'general':
        items[-2:] = domain_questions(level, domain)
    if seed is not None:
        rng = random.Random(seed)
        for item in items:
            answer = item.correct_option_id
            rng.shuffle(item.options)
            for index, option in enumerate(item.options):
                was_correct = option.id == answer
                option.id = chr(97 + index)
                if was_correct:
                    item.correct_option_id = option.id
    return f'{VERSION}/{level}/{domain}', items
